%[text] # FRFT Example
%[text] 
%[text] 
%[text] Creating a rectangular pulse abd calculating frft at various values of alpha.
fs = 2000 %[output:668c0307]
T = 0.25;
t = 0: 1/fs : T - 1/fs;
B = 500;
k = B/(2*T);
f0 = 0;

s1 = 2.5*chirp(t(1: fs*T),f0,k);
%%
%s1 = [s1,zeros(1,250),s1,zeros(1,250)];

rrc_filter = comm.RaisedCosineTransmitFilter(RolloffFactor=0.3, ...
        Shape='Normal', ...
        FilterSpanInSymbols=2, ...
        OutputSamplesPerSymbol=10);
rrc_filter.Gain = 1/max(coeffs(rrc_filter).Numerator) %[output:050c930a]

s2_bits = 2*(round(rand(1,length(t)/10))-0.5);
s2 = rrc_filter(s2_bits);
s2 = s2(:)';
s = s1 + s2;

alpha = 0: 1 / 50 : 2;

s_frft = zeros(length(alpha),length(s));

for i = 1:length(alpha)
    s_frft(i,:) = frft(s,alpha(i));
end

s_frft_sqmag = abs(s_frft).^2;

S = sqrt(T/fs) %[output:8ace33f2]
plot(t,real(s)) %[output:646e1423]
plot(t,real(s1),t,s2); %[output:0dcd81b3]

fig = figure();  %[output:86af25ce]
fig.Position(3:4) = [1000, 500]; %[output:86af25ce]

subplot(2,1,1) %[output:86af25ce]
frft_plot = imagesc(alpha,0:length(s)-1,10*log10(s_frft_sqmag)); %[output:86af25ce]
xticks([0, pi/4, pi/2, 3*pi/4, pi]) %[output:86af25ce]
xticklabels({'0', '\pi/4', '\pi/2', '3\pi/4', '\pi'}) %[output:86af25ce]
xlabel('\alpha (radians)') %[output:86af25ce]
ylabel(" u ") %[output:86af25ce]
zlabel("|X_\alpha (u)|^2") %[output:86af25ce]
colormap(gca,hot), colorbar %[output:86af25ce]
%Place datatip at peak value
[frft_maxval,frft_maxidx] = max(s_frft,[],"all");
frft_maxtip = datatip(frft_plot,'DataIndex',frft_maxidx,'Location','southwest'); %[output:86af25ce]
frft_plot.DataTipTemplate.DataTipRows(end+1) = dataTipTextRow("Magnitude",s_frft_sqmag); %[output:86af25ce]

subplot(2,1,2) %[output:86af25ce]
plot(alpha,max(10*log10(s_frft_sqmag'))) %[output:86af25ce]
ylabel("max(|X_\alpha (u)|^2)") %[output:86af25ce]
xticks([0, pi/4, pi/2, 3*pi/4, pi]) %[output:86af25ce]
xticklabels({'0', '\pi/4', '\pi/2', '3\pi/4', '\pi'}) %[output:86af25ce]
hold on; %[output:86af25ce]
xline(alpha(mod(frft_maxidx,length(alpha))), 'r--', 'LineWidth', 1.5); %[output:86af25ce]
hold off; %[output:86af25ce]
%[text] 

fig = figure();  %[output:7004b59c]
frft_surf = surface(alpha,0:length(s)-1,s_frft_sqmag'); %[output:7004b59c]
frft_surf.AlphaData = 0; %[output:7004b59c]
shading interp %[output:7004b59c]
xticks([0, pi/4, pi/2, 3*pi/4, pi]) %[output:7004b59c]
xticklabels({'0', '\pi/4', '\pi/2', '3\pi/4', '\pi'}) %[output:7004b59c]
xlim([pi/4, pi/2,]) %[output:7004b59c]
ylim([100,400]) %[output:7004b59c]
xlabel('\alpha') %[output:7004b59c]
ylabel(" u ") %[output:7004b59c]
zlabel("|X_\alpha (u)|^2") %[output:7004b59c]
view([344 61]) %[output:7004b59c]
colorbar %[output:7004b59c]
%%
%[text] Cancelling the interference
s_frft_cancelled = s_frft;
s_frft_cancelled(s_frft_sqmag > 175) = 0; %[control:slider:1946]{"position":[33,36]}
s_frft_cancelled_row = s_frft_cancelled(mod(frft_maxidx,size(s_frft,1)),:);
s_frft_cancelled_alpha = alpha(mod(frft_maxidx,size(s_frft,1)));


s_ifrft = frft(s_frft_cancelled_row,-s_frft_cancelled_alpha/(pi/2));


fig = figure();  %[output:0207b596]
fig.Position(3:4) = [2000, 1000]; %[output:0207b596]
subplot(2,2,1);plot(t,real(s_ifrft));subplot(2,2,2);plot(t,imag(s_ifrft)); %[output:0207b596]
subplot(2,2,3);plot(t,real(s_ifrft),t,real(s1));subplot(2,2,4);plot(t,real(s_ifrft),t,s2); %[output:0207b596]





